      if (fam == 0 && items == 1 || fam == 11) cc = top ? vec3(0.9, 0.8, 0.6) : vec3(1.2, 1.0, 0.8); // lit display case
      if (fam == 4) cc = top ? vec3(0.2) + vec3(0.6, 0.8, 1.2) * step(0.5, fract(C.x * 2.0)) : vec3(0.15);
      if (fam == 3 && !top) cc += vec3(0.6, 0.1, 0.5) * step(C.y, 0.08);
